 {view==='return'&&<><p className="cg-kicker">03 · {t('BACK WITH A SMALL UPDATE','带着一点发现回来')}</p><h1>{t('How did it feel for you?','这次，你的感受如何？')}</h1><div className="cg-split"><div><Photo id={w.updatePhoto} lang={lang}/><div className="cg-photo-picker">{(Object.keys(photos) as PhotoId[]).map(id=><button aria-label={t('Choose scenario photo ','选择情境图片 ')+id} aria-pressed={w.updatePhoto===id} key={id} onClick={()=>change({updatePhoto:id},'update_photo_selected',{photo:id})}><Photo id={id} lang={lang}/>{w.updatePhoto===id&&<Check size={18}/>}</button>)}</div><p className="cg-meta">{t('Scenario images, not before-and-after evidence.','图片为情境道具，不是前后效果证据。')}</p></div><div className="cg-stack"><details className="cg-task"><summary>{t('Open the supplied scenario card','查看提供的情境卡')}</summary><p>{tx(st.task)}</p><p>{t('Describe it in your own words; no real product trial is required.','请用自己的话描述，无需进行真实产品试验。')}</p></details>{w.plan&&<p className="cg-muted">{t('Your thought: ','你之前的想法：')}{w.plan}</p>}<label className="cg-field">{t('A small update','一句近况')}<textarea rows={4} maxLength={800} value={w.updateDraft} onChange={e=>change({updateDraft:e.target.value})} placeholder={t('I tried… I noticed… I’m still unsure about…','我试了……注意到……还不确定……')}/></label><details><summary>{t('Anything else someone should know?','还有什么值得让对方知道？')}</summary><label className="cg-field">{t('Context, if useful','想补充的情境')}<input maxLength={240} value={w.context} onChange={e=>change({context:e.target.value})}/></label><label className="cg-field">{t('What is still open?','还有什么尚不确定？')}<input maxLength={240} value={w.limits} onChange={e=>change({limits:e.target.value})}/></label></details><Button className="cg-primary" disabled={publishing||!w.updateDraft.trim()||!w.question||!w.responseShown} onClick={()=>share('update',w.updateDraft,()=>{change({updates:[...w.updates,{id:crypto.randomUUID(),text:w.updateDraft.trim(),photo:w.updatePhoto,context:w.context.trim(),limits:w.limits.trim(),at:new Date().toISOString()}]},'return_shared');go('thanks');},{photo:w.updatePhoto,context:w.context,limits:w.limits})}>{t('Share my update','分享这次近况')}<ArrowRight size={18}/></Button><button className="cg-text-link" onClick={()=>{go('profile');setNotice(t('Draft kept on this device.','草稿已保留在本机。'));}}>{t('Keep it as a draft','先保留为草稿')}</button></div></div></>}
 {view==='thanks'&&<><p className="cg-kicker">{t('A MOMENT WORTH KEEPING','值得记住的一刻')}</p><h1>{t('You came back. The story continues.','你回来了，故事也继续了。')}</h1>{last?<div className="cg-split"><Photo id={last.photo} lang={lang}/><div className="cg-stack"><div className="cg-moment"><Heart size={25}/><strong>{t('A return, remembered','记住这一次回访')}</strong><p>{last.text}</p></div><label className="cg-field">{t('A note to ','对 ')}{st.guide}{t(' · optional',' 说句话 · 可选')}<textarea rows={3} maxLength={400} value={w.thanksDraft} onChange={e=>change({thanksDraft:e.target.value})} placeholder={t('What part of their help mattered to you?','对方的哪一点帮助让你印象深刻？')}/></label>{w.thanks&&<p className="cg-muted">{t('Your note: ','你写下的感谢：')}{w.thanks}</p>}<Button className="cg-primary" disabled={publishing||!w.thanksDraft.trim()} onClick={()=>share('thanks',w.thanksDraft,()=>{change({thanks:w.thanksDraft.trim()},'thanks_shared',{to:st.guide});setNotice(t('Your note is connected to this conversation.','你的感谢已与这段讨论连在一起。'));},{to:w.selectedQuoteAuthor||st.guide})}>{t('Share my thank-you','分享我的感谢')}</Button><Button className="cg-secondary" variant="outline" onClick={draftAlbum}>{t('Keep our story in an album','把我们的故事放进图册')}</Button><p className="cg-meta">{t('You can continue without sending a thank-you.','不发送感谢也可以继续。')}</p></div></div>:<Button onClick={()=>go('return')}>{t('Write an update','写一条回访')}</Button>}</>}
 {view==='draft'&&<><p className="cg-kicker">04 · {t('OUR SHARED BEAUTY NOTES','我们共同的美妆笔记')}</p><h1>{t('Keep the story. Keep the people.','留下经验，也留下彼此。')}</h1><div className="cg-split"><div><Photo id={last?.photo||st.photo} lang={lang}/><div className="cg-lineage"><span>{st.member}</span><ArrowRight size={16}/><span>{w.selectedQuoteAuthor||st.guide}</span><ArrowRight size={16}/><span>{t('You','你')}</span></div><p className="cg-meta">{t('Question · guidance · your return','提问 · 示范与建议 · 你的回访')}</p></div><div className="cg-stack"><label className="cg-field">{t('A title for this story','给故事取个名字')}<input maxLength={100} value={w.albumTitle} onChange={e=>change({albumTitle:e.target.value})}/></label><label className="cg-field">{t('What would you keep?','你想留下什么？')}<textarea rows={5} maxLength={1800} value={w.albumDraft} onBlur={()=>draftEdited('album',w.albumDraft)} onChange={e=>change({albumDraft:e.target.value})}/></label><label className="cg-field">{t('Leave room for another experience','为不同经验留一点空间')}<input maxLength={400} value={w.albumLimits} placeholder={t('This may be different when…','换个情境，也许会……')} onChange={e=>change({albumLimits:e.target.value})}/></label><Button className="cg-ai" variant="outline" onClick={()=>ai('album')}><Sparkles size={17}/>{t('Help arrange my words','帮我整理已有表达')}</Button>{inlinePanel('album')}{trace('album')}{originalDrafts[story+':album']!==undefined&&<button className="cg-text-link" onClick={()=>change({albumDraft:originalDrafts[story+':album']},'original_restored',{kind:'album'})}>{t('Restore my wording','恢复我的原话')}</button>}<Button className="cg-primary" disabled={!last||!w.albumTitle.trim()||!w.albumDraft.trim()} onClick={()=>{setReviewed(false);setModal('review');event('album_review_opened',{version:w.versions.length+1});}}>{t('Preview our album entry','预览这页共同图册')}</Button></div></div></>}
 {view==='album'&&<><section className="cg-gallery-hero"><div className="cg-gallery-orbit"><Photo id="swatches" lang={lang}/><Photo id="base" lang={lang}/><Photo id="blush" lang={lang}/></div><h1>{t('Gallery','图 册')}</h1><p>{t('See and be seen. Post and browse photos and videos from community members.','看见别人，也让自己被看见。浏览成员分享的图片与视频。')}</p><button className="cg-gallery-search" onClick={()=>setNotice(t('Browse the scenario photos below.','请浏览下方情境图片。'))}><Search size={19}/>{t('Search Photos…','搜索图片……')}</button></section><div className="cg-gallery-carousel">{(active?[story]:['A','B','C'] as StoryId[]).map(id=><button key={id} onClick={()=>openStory(id)}><Photo id={stories[id].photo} lang={lang}/></button>)}{!active&&<button onClick={()=>openStory('C')}><Photo id="swatches" lang={lang}/></button>}</div><div className="cg-gallery-toolbar"><div><button className="is-active">{t('All Photos','全部图片')}</button><button onClick={()=>go('profile')}>{t('My Photos','我的图片')}</button></div><button onClick={()=>last?draftAlbum():go('return')}><Camera size={19}/>{t('Add a Photo','添加图片')}</button></div><div className="cg-gallery-controls"><label><input type="checkbox" onChange={()=>setNotice(t('This simulation keeps the same photo set for comparison.','本模拟为对照测试保留同一组图片。'))}/>{t('Show photos from my beauty matches','显示与我相似成员的图片')}</label><div><button onClick={()=>setNotice(t('Filters are held constant in this study.','本研究保持筛选条件一致。'))}>{t('Filter','筛选')}<ChevronDown size={16}/></button><button onClick={()=>setNotice(t('Most recent scenario images are shown first.','较新的情境图片显示在前。'))}>{t('Sort: Most Recent','排序：最新')}<ChevronDown size={16}/></button></div></div><div className="cg-gallery-welcome"><div><strong>{t('NEW TO THE COMMUNITY?','初 来 社 区？')}</strong><p>{t('Follow a few simple steps to get started.','从几个简单步骤开始。')}</p><button onClick={()=>setModal('about')}>{t('LEARN MORE >','了解更多 >')}</button></div><div className="cg-welcome-face">✦</div></div><section className="cg-gallery-browse"><div className="cg-gallery-grid">{(active?[story]:['A','B','C'] as StoryId[]).map(id=><button key={id} onClick={()=>openStory(id)}><Photo id={stories[id].photo} lang={lang}/><div className="cg-gallery-product-row"><span>◈</span><span>◌</span><span>✦</span></div><strong>{tx(stories[id].title)}</strong><small>{t('in Group · ','所在群组 · ')}{tx(caseTopics[id].group)}</small><span className="cg-gallery-member"><i>{stories[id].member[0]}</i>{stories[id].member}<em>{t('INSIDER','成员')}</em></span></button>)}{!active&&<button onClick={()=>openStory('C')}><Photo id="swatches" lang={lang}/><div className="cg-gallery-product-row"><span>◌</span><span>✦</span><span>◇</span></div><strong>{t('Swatches in another light','另一种光线下的试色')}</strong><small>{t('in Group · Swatches and shades','所在群组 · 试色与色号')}</small><span className="cg-gallery-member"><i>L</i>Lea<em>{t('INSIDER','成员')}</em></span></button>}</div></section>
{album?<><div className="cg-split"><div><VisualRef id={album.anchor?.photo||album.photo} lang={lang} anchor={album.anchor}/><p className="cg-meta">{t('Original question reference','原提问指代')}</p>{album.anchor&&album.photo!==album.anchor.photo&&<><Photo id={album.photo} lang={lang}/><p className="cg-meta">{t('Return photo · scenario prop','回访图片 · 情境道具')}</p></>}</div><div className="cg-stack"><span className="cg-kicker">{t('REVIEWED STORY · DESIGN PROPOSAL','已核对的故事 · 本研究新增设计')} · {album.version}</span><h2>{album.title}</h2>{album.quotedLine&&<div className="cg-linked-quote"><span>↳</span><div><strong>{t('Human reply retained','保留的成员回应')}</strong><p>{album.quotedLine}</p></div></div>}<p className="cg-preserve">{album.text}</p>{album.limits&&<div className="cg-open-question"><strong>{t('Still room to explore','还可以继续摸索')}</strong><p>{album.limits}</p></div>}<div className="cg-lineage">{album.authors.map((a,i)=><span key={i}>{a==='You'?t('You','你'):a}</span>)}</div><p className="cg-meta">{t('Image detail 1 → selected human sentence → return → reviewed album. Scenario roles, not co-author approvals.','图片细节 1 → 选中的成员原句 → 回访 → 已核对图册。这里是情境角色，不代表共同作者已认可。')}</p><Button className="cg-primary" onClick={()=>go('pass')}>{t('Pass this experience on','把这段经验传下去')}<ArrowRight size={18}/></Button><Button variant="outline" className="cg-secondary" onClick={()=>{change({albumTitle:album.title,albumDraft:album.text,albumLimits:album.limits});go('draft');}}>{t('Add a different perspective','补充一种不同的看法')}</Button><button className="cg-text-link" onClick={()=>{setModal('history');event('history_opened');}}><History size={17}/>{t('The story behind this page','这一页的来历与变化')}</button></div></div></>:<div className="cg-empty cg-album-empty"><Photo id="swatches" lang={lang}/><h2>{t('Your shared story starts with a return.','从一次回访，开始你的共同故事。')}</h2><p>{t('Keep an experience with the people and context that shaped it.','把经验与帮助过你的人、当时的情境一起留下。')}</p><Button className="cg-primary" onClick={last?draftAlbum:()=>go(w.question?'return':'detail')}>{last?t('Create our first page','写下共同的第一页'):t('Return to a conversation','回到一段讨论')}</Button></div>}</>}
 {view==='pass'&&<><p className="cg-kicker">05 · {t('A NEWCOMER ASKS','又一位新人开口了')}</p><h1>{t('Now you have something to share.','现在，你也有可以分享的经历。')}</h1><div className="cg-split"><div className="cg-stack"><div className="cg-mentor"><div className="cg-member-line"><span className="cg-avatar">J</span><span><strong>Jules</strong><small>{t('Scenario newcomer','情境中的新成员')}</small></span></div><p>{tx(st.newcomer)}</p></div>{album&&<div className="cg-context"><VisualRef id={album.anchor?.photo||album.photo} lang={lang} anchor={album.anchor} mini/><div><strong>{album.title}</strong><p>{t('Linked with its visual detail, contributors and limits','连同视觉细节、贡献者与适用边界一起分享')}</p></div></div>}</div><div className="cg-stack"><label className="cg-field">{t('Your reply to Jules','你给 Jules 的回应')}<textarea rows={5} maxLength={800} value={w.passDraft} onBlur={()=>draftEdited('pass',w.passDraft)} onChange={e=>change({passDraft:e.target.value})} placeholder={t('One thing that helped me… It might be different for you…','有一点曾经帮到我……对你来说，也许会不同……')}/></label><Button className="cg-ai" variant="outline" disabled={!album} onClick={()=>ai('pass')}><Sparkles size={17}/>{t('Prepare a reply with its source and limits','结合来源与边界准备回应')}</Button>{inlinePanel('pass')}{trace('pass')}{originalDrafts[story+':pass']!==undefined&&<button className="cg-text-link" onClick={()=>change({passDraft:originalDrafts[story+':pass']},'original_restored',{kind:'pass'})}>{t('Restore my wording','恢复我的原话')}</button>}<Button className="cg-primary" disabled={publishing||!album||!w.passDraft.trim()} onClick={()=>share('handoff',w.passDraft,()=>{change({passed:w.passDraft.trim()},'help_passed_on',{albumVersion:album?.version});go('profile');},{albumVersion:album?.version,to:'Jules (scripted role)'})}>{t('Reply with our album story','带着图册故事回复')}<ArrowRight size={18}/></Button><p className="cg-meta">{t('Jules is a scripted role. Your reply is saved in this test conversation.','Jules 是脚本角色。你的回复会保存在这段测试讨论中。')}</p></div></div></>}
 {view==='profile'&&<><p className="cg-kicker">{t('MY MOMENTS','我的社区时刻')}</p><h1>{t('Small gestures. A shared history.','小小的回应，共同的记忆。')}</h1><p className="cg-intro">{t('A collection of how you took part. No points, no ranking.','记住你怎样参与过，没有积分和排名。')}</p><div className="cg-moment-grid">{Object.entries(momentNames).map(([key,label])=><div className={'cg-moment '+(moments(w).includes(key)?'earned':'waiting')} key={key}><Heart size={22}/><h2>{tx(label)}</h2><p>{moments(w).includes(key)?t('Recorded in this local story','已留在这段本地故事里'):t('Whenever you feel ready','在你愿意的时候')}</p></div>)}</div>{w.passed&&<div className="cg-mentor"><strong>{t('What you passed on','你传下去的帮助')}</strong><p>{w.passed}</p></div>}<div className="cg-actions"><Button className="cg-primary" onClick={()=>go('detail')}>{t('Continue the conversation','继续这段交流')}</Button><Button className="cg-secondary" variant="outline" onClick={()=>go('return')}>{t('Return to my draft','回到我的回访草稿')}</Button>{active&&<Button className="cg-secondary" variant="outline" onClick={()=>setModal('ratings')} disabled={!canFinish(w)}>{t('Reflect on this activity','回顾这次活动')}</Button>}</div></>}
 {view==='assistant'&&<><p className="cg-kicker">{t('SEPARATE ASSISTANT WORKSPACE','独立助手工作区')}</p><h1>{t('A useful thread, not a final answer.','一条线索，留出你的判断。')}</h1><div className="cg-reading-width"><p className="cg-meta">{t('Bring the current community reference into this separate workspace before viewing the same suggestion.','先把当前社区指代带入独立工作区，再查看相同的建议。')}</p>{!separateContextLoaded?<Button className="cg-secondary" variant="outline" onClick={()=>{setSeparateContextLoaded(true);event('assistance_context_transferred',{kind:assistKind,anchor:w.anchor,quote:w.selectedQuote});}}>{t('Bring the selected context here','把选中的情境带到这里')}</Button>:assistPanel}</div></>}
 {view==='done'&&<div className="cg-reading-width"><p className="cg-kicker">{t('SESSION COMPLETE','会话已完成')}</p><h1>{t('Thank you for taking part.','谢谢你的参与。')}</h1><p>{t('Your activities are saved in this browser. Export a copy before clearing this session.','活动已保存在本机，请在清除前导出副本。')}</p><p role="status">{onlineConfigured?(cloudStatus==='saved'?t('Research record saved online.','研究记录已保存到数据库。'):cloudStatus==='error'?t('Online save failed. Keep this tab open and export a copy.','数据库保存失败，请保留此页并导出副本。'):t('Saving research record…','正在保存研究记录……')):''}</p><div className="cg-actions"><Button className="cg-primary" onClick={()=>download('json')}>JSON</Button><Button className="cg-secondary" variant="outline" onClick={()=>download('csv')}>CSV</Button></div><details><summary>{t('Preview export / copy manually','预览导出 / 手动复制')}</summary><label className="cg-field">JSON<textarea readOnly rows={8} value={exportText('json')}/></label><label className="cg-field">CSV<textarea readOnly rows={5} value={exportText('csv')}/></label></details><Button className="cg-secondary" variant="outline" onClick={()=>setModal('erase')}>{t('Clear this session','清除此会话')}</Button></div>}
